/* =====================================================================
   📜 Rotulus
   ===================================================================== */

/* Themed fonts */
@import url('https://fonts.googleapis.com/css2?family=IM+Fell+English&family=MedievalSharp&display=swap');

.callout[data-callout="vintage"] {
  --callout-color: 120, 85, 45;
  --callout-icon: lucide-vintage;
  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
  margin: 1.75em 0;
}

/* ---------------------------------------------------------------
   TOP ROD (the callout title bar)
   --------------------------------------------------------------- */
.callout[data-callout="vintage"] .callout-title {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 34px;
  margin: 0 14px;
  padding: 0 10px;
  background:
    repeating-linear-gradient(90deg, rgba(0, 0, 0, 0.08) 0px, rgba(0, 0, 0, 0.08) 1px, transparent 2px, transparent 6px),
    linear-gradient(180deg, #8a5a30 0%, #5c3418 45%, #3a2109 100%);
  border-radius: 17px;
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.4), inset 0 2px 2px rgba(255, 255, 255, 0.18);
  font-family: 'MedievalSharp', serif;
  font-weight: 600;
  font-size: 0.95em;
  color: #ffd8a1 !important;
  letter-spacing: 0.5px;
  z-index: 2;
}

/* ---------------------------------
  Wooden knobs 
  ----------------------------------*/

.callout[data-callout="vintage"] .callout-title::before,
.callout[data-callout="vintage"] .callout-title::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  transform: translateY(-50%);
  background:
    repeating-radial-gradient(circle at 38% 34%, rgba(0, 0, 0, 0.12) 0px, rgba(0, 0, 0, 0.12) 1px, transparent 1.6px, transparent 3.4px),
    radial-gradient(circle at 32% 26%, #d1a468 0%, #a8703c 32%, #6b3f1d 68%, #331c0a 100%);
  box-shadow:
    inset 0 0 0 2px rgba(0, 0, 0, 0.35),
    inset -3px -3px 5px rgba(0, 0, 0, 0.45),
    inset 2px 2px 4px rgba(255, 224, 178, 0.4),
    0 2px 5px rgba(0, 0, 0, 0.55);
}
.callout[data-callout="vintage"] .callout-title::before { left: -15px; }
.callout[data-callout="vintage"] .callout-title::after  { right: -15px; }

/* swap the default icon for a vintage emoji */
.callout[data-callout="vintage"] .callout-icon svg { display: none; }
.callout[data-callout="vintage"] .callout-title-inner::before {
  content: "📜";
  margin-right: 4px;
}

.callout[data-callout="vintage"] .callout-fold {
  color: #ffd8a1 !important;
  opacity: 1;
}

/* ---------------------------------------------------------------
   PARCHMENT (the callout content, visible when unrolled)
   --------------------------------------------------------------- */
.callout[data-callout="vintage"] .callout-content {
  position: relative;
  margin: 0 6px;
  padding: 26px 32px 30px;
  background:
    radial-gradient(ellipse at 50% 50%, transparent 45%, rgba(64, 38, 12, 0.38) 100%),
    radial-gradient(ellipse at 14% 18%, rgba(110, 75, 30, 0.22), transparent 30%),
    radial-gradient(ellipse at 88% 12%, rgba(110, 75, 30, 0.18), transparent 26%),
    radial-gradient(ellipse at 78% 82%, rgba(110, 75, 30, 0.2), transparent 32%),
    radial-gradient(ellipse at 22% 88%, rgba(110, 75, 30, 0.17), transparent 28%),
    radial-gradient(ellipse at 55% 45%, rgba(110, 75, 30, 0.1), transparent 40%),
    linear-gradient(135deg, #efdfb4 0%, #e3ce9d 50%, #d7bd85 100%);
  border-left: 0px solid #b89b62;
  border-right: 0px solid #b89b62;
  color: #4a3319;
  font-family: 'IM Fell English', serif;
  font-size: 1.05em;
  line-height: 1.75;
  box-shadow: inset 0 0 30px rgba(90, 60, 20, 0.25);
  overflow: hidden;
}


/* ----------------------------------------------------------------------------
    PARCHMENT BACKGROUND IMAGE (optional, for more realistic and asthetic look)
   ----------------------------------------------------------------------------
*/


.callout[data-callout="vintage"] .callout-content::before {
    content: "";
    position: absolute;
    top: 0%;
    width: 1800px;
    height: 400px;
    border-radius: 0%;
    transform: translateY(-10%);
    transform: translateX(-18%);
    /*inset: 0; */

    background: url("data:image/png;base64,")
                center center / cover 
                no-repeat;

    opacity: .55;

    mix-blend-mode: multiply;

    pointer-events: none;
}


/* ---------------------------------------------------------------
   BOTTOM ROD
   --------------------------------------------------------------- */
.callout[data-callout="vintage"]::after {
  content: "";
  display: block;
  height: 20px;
  margin: 4px 20px 0;
  background:
    repeating-linear-gradient(90deg, rgba(0, 0, 0, 0.08) 0px, rgba(0, 0, 0, 0.08) 1px, transparent 2px, transparent 6px),
    linear-gradient(180deg, #8a5a30 0%, #5c3418 45%, #3a2109 100%);
  border-radius: 10px;
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.4), inset 0 2px 2px rgba(255, 255, 255, 0.15);
}

/* collapsed: rods sit snug together = a fully rolled vintage */
.callout[data-callout="vintage"].is-collapsed .callout-content {
  display: none;
}
.callout[data-callout="vintage"].is-collapsed::after {
  margin-top: -2px;
}

/* gentle hover feedback on the title (click target for folding) */
.callout[data-callout="vintage"] .callout-title:hover {
  filter: brightness(1.08);
  cursor: pointer;
}


/* --- Force Title Color --- */
.callout[data-callout="vintage"] .callout-title-inner {
  color: #d4ad80 !important;
}

/* --- Force Content Color --- */
.callout[data-callout="vintage"] .callout-content p,
.callout[data-callout="vintage"] .callout-content h1,
.callout[data-callout="vintage"] .callout-content h2,
.callout[data-callout="vintage"] .callout-content h3,
.callout[data-callout="vintage"] .callout-content strong,
.callout[data-callout="vintage"] .callout-content em,
.callout[data-callout="vintage"] .callout-content ul,
.callout[data-callout="vintage"] .callout-content ol,
.callout[data-callout="vintage"] .callout-content li {
  color: #4a3319 !important;
}
